(function($){function setNavigation(){var path=window.location.pathname;path=path.replace(/\/$/,"");path=decodeURIComponent(path);$(".filter-list-item a").each(function(){var href=$(this).attr('href');href=href.replace(/\/$/,"");href=decodeURIComponent(href);if(href.indexOf(path)>=0){$(this).closest('.card-light-blue-btn').addClass('cat-selected')}})}
$(document).ready(function(){setNavigation()})})(jQuery)